import { MAX_BOX } from '@lexpad/core';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import styles from './BoxMeter.module.css';

/**
 * Which rung of the Leitner ladder a word is on, as five equal pieces
 * filled up to that rung.
 *
 * It replaced a pill reading "Box 3" tinted one of five shades of gold,
 * which asked the reader to know there are five boxes and that higher is
 * better before it told them anything. Five pieces say both without being
 * learnt. The number is still there for anybody who thinks in boxes, and
 * always in the accessible name.
 *
 * `rung` marks the piece that has just been reached, so a session can
 * light it as the word arrives.
 */
export function BoxMeter({
  box,
  label = false,
  rung = false,
  className,
}: {
  /** 1 to MAX_BOX. Anything outside is clamped. */
  box: number;
  /** Also print "Box 3", for screens with room to teach the system. */
  label?: boolean;
  /** Animate the newly filled bar; only ever true right after a grade. */
  rung?: boolean;
  className?: string | undefined;
}): React.JSX.Element {
  const at = Math.min(Math.max(Math.round(box), 1), MAX_BOX);
  return (
    <span
      className={cx(styles.meter, at === MAX_BOX && styles.done, className)}
      role="img"
      aria-label={t('word.boxOf', { box: at, total: MAX_BOX })}
    >
      <span className={styles.bars} aria-hidden="true">
        {Array.from({ length: MAX_BOX }, (_, index) => (
          <span
            key={index}
            className={cx(styles.bar, index < at && styles.on, rung && index === at - 1 && styles.rung)}
          />
        ))}
      </span>
      {label && (
        <span className={styles.text} aria-hidden="true">
          {t('session.box', { box: at })}
        </span>
      )}
    </span>
  );
}
